.darma-loader-three-dots-pulse{
  --td-dot: calc(var(--loader-size, 56px) / 5.6);
  --td-gap: calc(var(--loader-size, 56px) / 12);
  display:inline-flex;
  align-items:center;
  justify-content:center;
  gap:var(--td-gap);
  width:var(--loader-size, 56px);
  height:var(--loader-size, 56px);
}
.darma-loader-three-dots-pulse i{
  width:var(--td-dot);
  height:var(--td-dot);
  border-radius:50%;
  background-color:var(--loader-color, #6366f1);
}
.darma-loader-three-dots-pulse i{animation:darma-loader-three-dots-pulse-td-pulse var(--loader-speed, 1.5s) infinite linear}
.darma-loader-three-dots-pulse i:nth-child(2){animation-delay:calc(var(--loader-speed, 1.5s) / 5)}
.darma-loader-three-dots-pulse i:nth-child(3){animation-delay:calc(var(--loader-speed, 1.5s) / 2.5)}
@keyframes darma-loader-three-dots-pulse-td-pulse{
  0%,60%,100%{transform:scale(1);opacity:.45}
  30%{transform:scale(1.4);opacity:1}
}

